// Device and command-list vtable hooks: feature-query spoofing, PSO/command-signature logging,
// skip tokens for pipelines the hardware rejects, and dropping the work recorded against them.
#include <d3d12.h>
#include <dxgi1_4.h>
#include <algorithm>
#include <atomic>
#include <mutex>
#include <shared_mutex>
#include <unordered_map>
#include <string>
#include <unordered_set>
#include <vector>
#include "common.h"
#include "meshprof.h"
